class StockPrice { private val prices=HashMap<Int,Int>();private val counts=java.util.TreeMap<Int,Int>();private var latest=0;fun update(timestamp:Int,price:Int){prices[timestamp]?.let{old->counts[old]=counts[old]!!-1;if(counts[old]==0)counts.remove(old)};prices[timestamp]=price;counts[price]=(counts[price]?:0)+1;latest=maxOf(latest,timestamp)}fun current()=prices[latest]!!;fun maximum()=counts.lastKey();fun minimum()=counts.firstKey()}
